+// reviewGeneratedScript reviews in parts a candidate whose large generated file names `./gen/table.sh`
+// as its regenerating command, a script with a shebang line that writes the file, committed with the
+// permission bits mode. It returns the generated-file evidence of the review and the verdict.
+func reviewGeneratedScript(t *testing.T, mode os.FileMode) ([]GeneratedFile, Result) {
+	t.Helper()
+	r := newEdgeRepo(t)
+	start := r.commit("start", nil)
+	script := "#!/bin/sh\nexec > data/table.csv\nprintf '# Code generated by ./gen/table.sh; DO NOT EDIT.\\n'\ni=1\nwhile [ $i -le 800 ]; do echo \"row $i,value $i\"; i=$((i+1)); done\n"
+	r.write("gen/table.sh", script)
+	if err := os.Chmod(filepath.Join(r.root, "gen", "table.sh"), mode); err != nil {
+		t.Fatal(err)
+	}
+	r.write("data/table.csv", strings.Replace(generatedRows(800), "sh gen/table.sh", "./gen/table.sh", 1))
+	r.write("big.txt", exactly(reviewCeiling+20000, "b"))
+	r.commit("candidate", nil)
+	_, _, dir, res, err := wideReview(t, r, start)
+	if err != nil || res.Record.Verdict != "approve" || len(res.Record.Findings) != 0 {
+		t.Fatalf("the review is %q with findings %v, %v", res.Record.Verdict, res.Record.Findings, err)
+	}
+	raw, err := os.ReadFile(filepath.Join(dir, "executor-review", "review-1-material.json"))
+	if err != nil {
+		t.Fatal(err)
+	}
+	var ev Material
+	if err := json.Unmarshal(raw, &ev); err != nil {
+		t.Fatal(err)
+	}
+	return ev.Generated, res
+}
+
+// A marker command that runs a tracked executable script directly finds the script executable in the
+// scratch copy, so the regenerated file is identical and is summarised with its digest.
+func TestReviewInPartsRunsAnExecutableGeneratorDirectly(t *testing.T) {
+	got, _ := reviewGeneratedScript(t, 0o755)
+	text := strings.Replace(generatedRows(800), "sh gen/table.sh", "./gen/table.sh", 1)
+	want := []GeneratedFile{{Path: "data/table.csv", Command: "./gen/table.sh", SHA256: core.HashHex([]byte(text)), Outcome: "summarised"}}
+	if fmt.Sprint(got) != fmt.Sprint(want) {
+		t.Errorf("the evidence records %v, want %v", got, want)
+	}
+}
+
+// A script that is not executable in the reviewed tree is not executable in the scratch copy either:
+// the marker command cannot run it directly, so the file is kept, with no finding.
+func TestReviewInPartsDoesNotMakeAGeneratorExecutable(t *testing.T) {
+	got, _ := reviewGeneratedScript(t, 0o644)
+	text := strings.Replace(generatedRows(800), "sh gen/table.sh", "./gen/table.sh", 1)
+	want := []GeneratedFile{{Path: "data/table.csv", Command: "./gen/table.sh", SHA256: core.HashHex([]byte(text)), Outcome: "kept"}}
+	if fmt.Sprint(got) != fmt.Sprint(want) {
+		t.Errorf("the evidence records %v, want %v", got, want)
+	}
+}

